import re, sys
p = sys.argv[1]; s = open(p, encoding="utf-8").read()
new = "[\"Interface transverse\",\"En trois chapitres : le référencement (une seule adresse, des métadonnées qui disent noindex aux brouillons, un plan du site calculé à chaque demande, un robots.txt qui laisse passer les images publiques) ; le header (une liste de liens pour deux rendus, la page courante vue et entendue, la session dès le HTML, des signaux sans badge à zéro) ; l’accessibilité (des menus au clavier, des noms pour les icônes, des animations qui s’effacent, ce qui reste à faire).\",\"rédigée\"]"
